"""Skill-level completion contract helpers.

:class:`CompleteWhenSpec` is authored on skill frontmatter ``complete_when``.
Behavioural skill fields (tools, triggers, prose) live on
:class:`~rasa.mantle.skills.skill.Skill` / ``body``.
"""

from __future__ import annotations

from pydantic import BaseModel, ConfigDict, model_validator

from rasa.mantle.skills.conditions import Condition


class CompleteWhenSpec(BaseModel):
    """Skill-level completion contract from frontmatter ``complete_when``.

    Authors must use a mapping with ``condition`` and/or ``criteria``.
    Step-level ``complete_when`` stays a plain expression string.
    """

    model_config = ConfigDict(frozen=True)

    condition: str | None = None
    criteria: tuple[str, ...] = ()

    @model_validator(mode="after")
    def _require_at_least_one(self) -> CompleteWhenSpec:
        if not self.condition and not self.criteria:
            raise ValueError(
                "complete_when must declare at least one condition or criterion"
            )
        return self


def step_complete_when_from_spec(
    spec: CompleteWhenSpec | None,
) -> Condition | None:
    """Use skill ``condition`` for the synthetic prose step (auto-complete).

    When ``criteria`` is authored, auto-complete is disabled: exit only via a
    successful gated ``complete`` that also runs the completion judge.
    """
    if spec is None or not spec.condition or spec.criteria:
        return None
    return spec.condition
